     3	public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
     4	{
     5	    public const int DailyLimit = 200;
     6	    public const int FeeThreshold = 100;
     7	    public const int WithdrawalFee = 5;
     8	    public const int MaxNotesPerPass = 4;
     9	    public const int CassetteCapacity = 5;
    10	
    11	    private static readonly Denomination[] Denominations = [Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
    12	
    13	    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    14	    {
    15	        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    16	        Operation.Deposit deposit => Deposit(account, deposit.Notes),
    17	        _ => throw new ArgumentException($"Opération inconnue : {operation}", nameof(operation)),
    18	    };
    19	
    20	    private AtmResult Withdraw(AccountState account, int amount)
    21	    {
    22	        if (amount <= 0 || amount % 10 != 0)
    23	        {
    24	            return Refuse(AtmStatus.InvalidAmount, account);
    25	        }
    26	
    27	        if (account.WithdrawnToday + amount > DailyLimit)
    28	        {
    29	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    30	        }
    31	
    32	        var fee = amount > FeeThreshold ? WithdrawalFee : 0;
    33	        if (amount + fee > account.Balance)
    34	        {
    35	            return Refuse(AtmStatus.InsufficientFunds, account);
    36	        }
    37	
    38	        if (FewestNotes(amount, Available()) is not { } combination)
    39	        {
    40	            return Refuse(AtmStatus.CannotDispense, account);
    41	        }
    42	
    43	        var dispensed = NoteCounts.None;
    44	        foreach (var pass in Passes(combination))
    45	        {
    46	            if (!dispenser.Dispense(pass))
    47	            {
    48	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    49	            }
    50	
    51	            dispensed += pass;
    52	        }
    53	
    54	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    55	
    56	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    57	    }
    58	
    59	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    60	    {
    61	        if (notes.Total <= 0)
    62	        {
    63	            return Refuse(AtmStatus.InvalidAmount, account);
    64	        }
    65	
    66	        if (dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    67	        {
    68	            return Refuse(AtmStatus.CassetteJammed, account);
    69	        }
    70	
    71	        var after = dispenser.Stock + notes;
    72	        if (Denominations.Any(d => after.Of(d) > CassetteCapacity))
    73	        {
    74	            return Refuse(AtmStatus.CassetteFull, account);
    75	        }
    76	
    77	        if (!dispenser.Load(notes))
    78	        {
    79	            return Refuse(AtmStatus.DispenserFault, account);
    80	        }
    81	
    82	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    83	    }
    84	
    85	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
    86	        new(status, NoteCounts.None, 0, account);
    87	
    88	    /// <summary>Le stock utilisable : la cassette bloquée compte pour zéro.</summary>
    89	    private NoteCounts Available()
    90	    {
    91	        var stock = dispenser.Stock;
    92	
    93	        return dispenser.Jammed switch
    94	        {
    95	            Denomination.Fifty => stock with { Fifties = 0 },
    96	            Denomination.Twenty => stock with { Twenties = 0 },
    97	            Denomination.Ten => stock with { Tens = 0 },
    98	            _ => stock,
    99	        };
   100	    }
   101	
   102	    /// <summary>La combinaison exacte qui compte le moins de billets, ou <c>null</c>.</summary>
   103	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   104	    {
   105	        NoteCounts? best = null;
   106	        for (var fifties = 0; fifties <= available.Fifties && fifties * 50 <= amount; fifties++)
   107	        {
   108	            for (var twenties = 0; twenties <= available.Twenties && fifties * 50 + twenties * 20 <= amount; twenties++)
   109	            {
   110	                var rest = amount - fifties * 50 - twenties * 20;
   111	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   112	                {
   113	                    continue;
   114	                }
   115	
   116	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   117	                if (best is not { } current || candidate.Total < current.Total)
   118	                {
   119	                    best = candidate;
   120	                }
   121	            }
   122	        }
   123	
   124	        return best;
   125	    }
   126	
   127	    /// <summary>Découpe une combinaison en passages d'au plus <see cref="MaxNotesPerPass"/> billets.</summary>
   128	    private static IEnumerable<NoteCounts> Passes(NoteCounts notes)
   129	    {
   130	        var remaining = notes;
   131	        while (remaining.Total > 0)
   132	        {
   133	            var room = MaxNotesPerPass;
   134	            var fifties = Math.Min(room, remaining.Fifties);
   135	            room -= fifties;
   136	            var twenties = Math.Min(room, remaining.Twenties);
   137	            room -= twenties;
   138	            var tens = Math.Min(room, remaining.Tens);
   139	
   140	            var pass = new NoteCounts(fifties, twenties, tens);
   141	            remaining -= pass;
   142	
   143	            yield return pass;
   144	        }
   145	    }
   146	}
